#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

int main() {
    int tt;
    cin >> tt;
    while(tt--)
    {
        int n;
        cin >> n;
        vector<ll> v(3*n + 1);
        for(int i=1; i<=3*n; i++) cin >> v[i];
        sort(v.begin(), v.end());
        vector<ll>pref(3*n+1);
        for(int i=1; i<=3*n; i++)
        {
            pref[i] = pref[i-1] + v[i];
        }
        ll ans = 0;
        for(int a=0; a<=n; a++)
        {
            ll now = 6*(pref[3*n] - pref[3*n - a]);
            int l = 0, r = n - a;
            ll s = 0;
            while(l <= r)
            {
                int m1 = l + (r-l)/3, m2 = r - (r-l)/3;
                ll cost1 = 4*(pref[3*n - a] - pref[3*n - a - 2*m1]) + 
                            3*(pref[3*n - a - 2*m1] - pref[2*a + m1]);
                ll cost2 = 4*(pref[3*n - a] - pref[3*n - a - 2*m2]) + 
                            3*(pref[3*n - a - 2*m2] - pref[2*a + m2]);
                            
                if(cost1 < cost2)
                {
                    s = max(s, cost2);
                    l = m1 + 1;
                }
                else if(cost1 >= cost2)
                {
                    s = max(s, cost1);
                    r = m2 - 1;
                }
            }
            ans = max(ans, now + s);
        }
        cout << ans << '\n';
    }
}
